'use strict';

// MODULES //

var canonicalBytes = require( '@data-apis/canonical/bytes' );
var sha256 = require( '@data-apis/canonical/sha256' );
var normalizeTimestamp = require( '@data-apis/report/normalize-timestamp' );
var parsePythonSeries = require( '@data-apis/report/parse-python-series' );
var seriesSchema = require( '@data-apis/series-schema' );


// FUNCTIONS //

/**
* Asserts that a value is a plain JSON object.
*
* @private
* @param {*} value - value
* @param {string} field - field name
*/
function requireObject( value, field ) {
	if ( !value || typeof value !== 'object' || Array.isArray( value ) ) {
		throw new Error( field + ' must be an object' );
	}
}

/**
* Asserts that an object contains exactly the allowed fields.
*
* @private
* @param {Object} value - object
* @param {Array<string>} fields - allowed and required fields
* @param {string} name - object name
*/
function requireExactFields( value, fields, name ) {
	var keys = Object.keys( value ).sort();
	var expected = fields.slice().sort();

	if ( JSON.stringify( keys ) !== JSON.stringify( expected ) ) {
		throw new Error( name + ' fields are malformed' );
	}
}

/**
* Asserts that a value is a bounded, trimmed string.
*
* @private
* @param {*} value - value
* @param {string} field - field name
* @param {number} [maximum=512] - maximum length
*/
function requireString( value, field, maximum ) {
	maximum = maximum || 512;
	if ( typeof value !== 'string' || value.length === 0 || value.length > maximum || value !== value.trim() ) {
		throw new Error( field + ' must be a bounded, trimmed string' );
	}
}

/**
* Validates report summary and test outcome agreement.
*
* @private
* @param {Object} data - report data
*/
function validateSummary( data ) {
	var summary = data.summary;
	var counts = new Map();
	var declared = 0;

	requireObject( summary, 'report.data.summary' );
	if ( !Object.hasOwn( summary, 'total' ) || !Object.hasOwn( summary, 'collected' ) ) {
		throw new Error( 'report.data.summary is missing totals' );
	}
	Object.entries( summary ).forEach( function validateCount( entry ) {
		if ( !/^[A-Za-z][A-Za-z0-9_-]*$/.test( entry[ 0 ] ) || !Number.isSafeInteger( entry[ 1 ] ) || entry[ 1 ] < 0 ) {
			throw new Error( 'report.data.summary contains an invalid count' );
		}
		if ( entry[ 0 ] !== 'total' && entry[ 0 ] !== 'collected' ) {
			declared += entry[ 1 ];
		}
	} );
	if ( !Array.isArray( data.tests ) || data.tests.length !== summary.total || summary.collected < summary.total || declared !== summary.total ) {
		throw new Error( 'report summary totals do not agree with tests' );
	}
	data.tests.forEach( function validateTest( item ) {
		requireObject( item, 'report.data.tests[]' );
		requireString( item.nodeid, 'report.data.tests[].nodeid', 16384 );
		requireString( item.outcome, 'report.data.tests[].outcome' );
		counts.set( item.outcome, ( counts.get( item.outcome ) || 0 ) + 1 );
	} );
	counts.forEach( function validateOutcome( count, outcome ) {
		if ( summary[ outcome ] !== count ) {
			throw new Error( 'report summary outcome does not agree with tests' );
		}
	} );
}


// MAIN //

/**
* Validates a report without loading third-party code.
*
* @param {Object} report - compliance report
* @param {string} expectedName - registered report name
* @returns {Object} validated and derived report metadata
*/
function validateReport( report, expectedName ) {
	var timestamp;
	var series;
	var seriesBytes;
	var bytes;

	requireObject( report, 'report' );
	requireExactFields( report, ['schema', 'name', 'version', 'api_version', 'timestamp', 'platform', 'python', 'test_suite', 'data'], 'report' );
	if ( report.schema !== 'v1' ) {
		throw new Error( 'Unsupported compliance report schema' );
	}
	['name', 'version', 'api_version', 'python'].forEach( function validateField( field ) {
		requireString( report[ field ], 'report.' + field );
	} );
	if ( report.name !== expectedName || !/^[0-9a-fA-F]{40}$/.test( report.test_suite ) ) {
		throw new Error( 'Report identity does not agree with the registry or schema' );
	}
	requireObject( report.platform, 'report.platform' );
	requireExactFields( report.platform, ['description', 'system', 'release', 'machine'], 'report.platform' );
	requireString( report.platform.description, 'report.platform.description', 16384 );
	['system', 'release', 'machine'].forEach( function validatePlatform( field ) {
		requireString( report.platform[ field ], 'report.platform.' + field );
	} );
	requireObject( report.data, 'report.data' );
	requireExactFields( report.data, ['duration', 'exitcode', 'summary', 'tests'], 'report.data' );
	if ( !Number.isFinite( report.data.duration ) || report.data.duration < 0 || ( report.data.exitcode !== 0 && report.data.exitcode !== 1 ) ) {
		throw new Error( 'Report duration or exit code is invalid' );
	}
	validateSummary( report.data );
	timestamp = normalizeTimestamp( report.timestamp );
	if ( timestamp !== report.timestamp ) {
		throw new Error( 'Stored report timestamp is not normalized' );
	}
	series = {
		'api_version': report.api_version,
		'python': parsePythonSeries( report.python ),
		'platform': {
			'system': report.platform.system,
			'machine': report.platform.machine
		}
	};
	seriesBytes = canonicalBytes( Object.assign( { 'series_schema': seriesSchema }, series ) );
	bytes = canonicalBytes( report );
	return {
		'bytes': bytes,
		'reportSha256': sha256( bytes ),
		'timestamp': timestamp,
		'series': series,
		'seriesSchema': seriesSchema,
		'seriesKey': 'sha256:' + sha256( seriesBytes )
	};
}


// EXPORTS //

module.exports = validateReport;
